	// But only for AckAll/AckFlowControl, since those guarantee no out-of-order acks.
	if recalcPending && seq == o.asflr+1 && o.isLeader() &&
		(o.cfg.AckPolicy == AckAll || o.cfg.AckPolicy == AckFlowControl) {
		o.npc += int64(len(o.pending))
