	o.pbytes, o.fcsz, o.fcid = 0, 0, _EMPTY_
	o.sseq, o.dseq = seq, 1
	o.adflr, o.asflr = o.dseq-1, o.sseq-1
	o.ldt, o.lat = time.Time{}, time.Time{}
	return recalcPending
